import unicodedata


def slugify(s):
    s = s.lower()
    # Decompose unicode characters (e.g. õ -> o + combining tilde)
    s = unicodedata.normalize('NFD', s)
    # Remove combining marks
    s = ''.join(c for c in s if not unicodedata.combining(c))

    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        else:
            out.append('-')

    result = ''.join(out)
    # Collapse consecutive dashes
    while '--' in result:
        result = result.replace('--', '-')
    return result.strip('-')

import unicodedata


def slugify(s):
    s = s.lower()
    # Normalize unicode to strip diacritics (e.g. õ -> o)
    s = unicodedata.normalize('NFD', s)
    s = ''.join(c for c in s if unicodedata.category(c) != 'Mn')

    out = []
    pending_dash = False
    for ch in s:
        if ch.isalnum():
            if pending_dash:
                out.append('-')
                pending_dash = False
            out.append(ch)
        else:
            pending_dash = True
    return ''.join(out)

